Theorem art_alloc_rep_free_pre : art_alloc_rep_b FSG (2 ^ 29) rn G' (lb_remove u LB) M'.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "SF0!1'=/rn;!2+<!2'>/rn;/M;!2+<!2'?/rn;/M;!2+<!4'@/FSG;/rn;/G;/M;!2+<!5'A/FSG;/rn;/G;/LB;/M;!2+<!5'B/FSG;/rn;/G;/LB;/M;!2+<!4'C/FSG;/rn;/G;/M;!2+<!4'D/FSG;/rn;/G;/M;!2+<!3'E/FSG;/G;/M;!2+<!4'F/FSG;/rn;/G;/LB;!4'G/FSG;/rn;/G;/M;!2'^8!1,8|10;!1,8|4d;!2'd>/u;/LB;!2'>/rn;/M';!2'?/rn;/M';!4'@/FSG;/rn;/G';/M';!5'A/FSG;/rn;/G';3/M';!5'B/FSG;/rn;/G';3/M';!5'eW/FSG;2/rn;/G';/M';!4'D/FSG;/rn;/G';/M';!3'E/FSG;/G';/M';!4'F/FSG;/rn;/G';3!4'G/FSG;/rn;/G';/M';!2+<<=!2+<;>!2+<:?!2+<9@!2+<8A!2+<7B!2+<6C!2+<5D&H;R/REP;!5'_:/FSG;/rn;/G;/LB;/M;!5'H01!6'fZ/FSG;2/rn;/G';3/M';$~R0$~R1!2$ROK;R0$_H;R1!4,^V0!2+<4E#2!4,^V4E'f[!4,^V5D'f\!4,^V6C'g0!4,^V7B'g1!4,^V8A'g2!4,^V9@'g3!4,^V:?'g4!4,^V;>'g5!4,^V<='g6'g7#2#1#1").
Qed.

(* [comment removed for export] *)
Theorem art_frep_bundle :
  art_alloc_rep_b FSG (2 ^ 29) rn G' (lb_remove u LB) M'
  /\ art_batches_bytes (g_qt FSG G') = art_batches_bytes qtl + n + (if newb then 8192 else 0)
  /\ (forall x : word, ~ art_free_fpl (U x) -> M' x = M x)
  /\ (forall b0 a, In b0 (lb_remove u LB) -> (fst b0 <= a < fst b0 + snd b0 \/ in_shadow_of (fst b0) (snd b0) a) -> ~ art_free_fpl a)
  /\ (forall a, 0 <= a < 2 ^ 64 -> art_out art_frep_W a -> ~ art_free_fpl a)
  /\ (forall a, rn_HI rn <= a -> ~ (Sp - 4096 <= a < Sp) -> ~ art_free_fpl a)
  /\ (forall a, 0x10000 <= a < 0x6c0000 -> ~ (0x23bdc8 <= a < 0x68bde8) -> ~ (0x16b100 <= a < 0x16b100 + 0x81030) -> ~ (0x1f9988 <= a < 0x1f9988 + 4) -> ~ art_free_fpl a)
  /\ (forall a len, ar_fs (rn_ar rn) <= a -> a + len <= ar_fs (rn_ar rn) + FS_BYTES -> art_gap art_frep_W a len)
  /\ (forall a len, rn_dtls rn <= a -> a + len <= rn_dtls rn + 4096 -> art_gap art_frep_W a len)
  /\ (forall a len, rn_t rn <= a -> a + len <= rn_t rn + 4096 -> (a + len <= rn_t rn + 80 \/ rn_t rn + 2888 <= a) -> art_gap art_frep_W a len)
  /\ (forall lo len a, 0 <= lo -> 0 < len -> lo + len <= 2 ^ 47 -> (lo + len <= rn_kbase rn \/ rn_kbase rn + 0x2000011000 <= lo) ->
